import{_ as t,o as s,c as r,l as a,t as o,N as i}from"./chunks/framework.Gjrf2Eoj.js";const _=JSON.parse('{"title":"ip-tcp_metrics | x-cmd man (ip man8) | management for TCP Metrics","titleTemplate":false,"description":"x-cmd man (ip man8 Manual Page) | ip-tcp_metrics - management for TCP Metrics","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ip-tcp_metrics | x-cmd man (ip man8) | management for TCP Metrics"}],["meta",{"name":"og:description","content":"x-cmd man (ip man8 Manual Page) | ip-tcp_metrics - management for TCP Metrics"}]]},"headers":[],"params":{"isMan":true,"man":"ip-tcp_metrics","category":"ip man8","desc":"management for TCP Metrics"},"relativePath":"ip/man8/ip-tcp_metrics.md","filePath":"ip/man8/ip-tcp_metrics.md"}'),n={name:"ip/man8/ip-tcp_metrics.md"},c={class:"visually-hidden"},p=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ip-tcp_metrics - management for TCP Metrics</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ip</strong> [ <em>OPTIONS</em> ] <strong>tcp_metrics</strong> { <em>COMMAND</em> | <strong>help</strong> }</p><p><strong>ip tcp_metrics</strong> { <strong>show</strong> | <strong>flush</strong>&quot;<strong>}</strong> <em>SELECTOR</em></p><p>**ip tcp_metrics delete <strong>[</strong> address **] <em>ADDRESS</em></p><p><em>SELECTOR</em> := [ [ <strong>address</strong> ] <em>PREFIX</em> ]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>ip tcp_metrics</strong> is used to manipulate entries in the kernel that keep TCP information for IPv4 and IPv6 destinations. The entries are created when TCP sockets want to share information for destinations and are stored in a cache keyed by the destination address. The saved information may include values for metrics (initially obtained from routes), recent TSVAL for TIME-WAIT recycling purposes, state for the Fast Open feature, etc. For performance reasons the cache can not grow above configured limit and the older entries are replaced with fresh information, sometimes reclaimed and used for new destinations. The kernel never removes entries, they can be flushed only with this tool.</p><h3 id="ip-tcp-metrics-show-show-cached-entries" tabindex="-1">ip tcp_metrics show - show cached entries <a class="header-anchor" href="#ip-tcp-metrics-show-show-cached-entries" aria-label="Permalink to &quot;ip tcp_metrics show - show cached entries&quot;">​</a></h3><dl><dt><strong>address</strong> * PREFIX** <em>(default)</em>*</dt><dd>IPv4/IPv6 prefix or address. If no prefix is provided all entries are shown.</dd></dl><p>The output may contain the following information:</p><p><strong>age</strong> * &lt;S.MMM&gt;** <em>sec</em>* - time after the entry was created, reset or updated with metrics from sockets. The entry is reset and refreshed on use with metrics from route if the metrics are not updated in last hour. Not all cached values reset the age on update.</p><p><strong>cwnd</strong> * &lt;N&gt;* - CWND metric value</p><p><strong>fo_cookie</strong> * &lt;HEX-STRING&gt;* - Cookie value received in SYN-ACK to be used by Fast Open for next SYNs</p><p><strong>fo_mss</strong> * &lt;N&gt;* - MSS value received in SYN-ACK to be used by Fast Open for next SYNs</p><p><strong>fo_syn_drops</strong> * &lt;N&gt;/&lt;S.MMM&gt;** <em>sec ago</em>* - Number of drops of initial outgoing Fast Open SYNs with data detected by monitoring the received SYN-ACK after SYN retransmission. The seconds show the time after last SYN drop and together with the drop count can be used to disable Fast Open for some time.</p><p><strong>reordering</strong> * &lt;N&gt;* - Reordering metric value</p><p><strong>rtt</strong> * &lt;N&gt;** <em>us</em>* - RTT metric value</p><p><strong>rttvar</strong> * &lt;N&gt;** <em>us</em>* - RTTVAR metric value</p><p><strong>ssthresh</strong> * &lt;SSTHRESH&gt;* - SSTHRESH metric value</p><p><strong>tw_ts</strong> * &lt;TSVAL&gt;/&lt;SEC&gt;** <em>sec ago</em>* - recent TSVAL and the seconds after saving it into TIME-WAIT socket</p><h3 id="ip-tcp-metrics-delete-delete-single-entry" tabindex="-1">ip tcp_metrics delete - delete single entry <a class="header-anchor" href="#ip-tcp-metrics-delete-delete-single-entry" aria-label="Permalink to &quot;ip tcp_metrics delete - delete single entry&quot;">​</a></h3><dl><dt><strong>address</strong> * ADDRESS** <em>(default)</em>*</dt><dd>IPv4/IPv6 address. The address is a required argument.</dd></dl><h3 id="ip-tcp-metrics-flush-flush-entries" tabindex="-1">ip tcp_metrics flush - flush entries <a class="header-anchor" href="#ip-tcp-metrics-flush-flush-entries" aria-label="Permalink to &quot;ip tcp_metrics flush - flush entries&quot;">​</a></h3><p>This command flushes the entries selected by some criteria.</p><p>This command has the same arguments as <strong>show.</strong></p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>ip tcp_metrics show address 192.168.0.0/24</p><blockquote><p>Shows the entries for destinations from subnet</p></blockquote><p>ip tcp_metrics show 192.168.0.0/24</p><blockquote><p>The same but address keyword is optional</p></blockquote><p>ip tcp_metrics</p><blockquote><p>Show all is the default action</p></blockquote><p>ip tcp_metrics delete 192.168.0.1</p><blockquote><p>Removes the entry for 192.168.0.1 from cache.</p></blockquote><p>ip tcp_metrics flush 192.168.0.0/24</p><blockquote><p>Removes entries for destinations from subnet</p></blockquote><p>ip tcp_metrics flush all</p><blockquote><p>Removes all entries from cache</p></blockquote><p>ip -6 tcp_metrics flush all</p><blockquote><p>Removes all IPv6 entries from cache keeping the IPv4 entries.</p></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><br> <strong>ip</strong>(8)</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Original Manpage by Julian Anastasov &lt;ja@ssi.bg&gt;</p>',46);function m(e,l,d,h,u,g){return s(),r("div",null,[a("h1",c,o(e.$params.man),1),p])}const S=t(n,[["render",m]]);export{_ as __pageData,S as default};
